import clsx from 'clsx';
import { Place } from '~/entities/shop/model/types';
import { usePhoneCall } from '~/shared/lib/hooks/use-phone-call';
import { overlay } from '~/shared/lib/overlay';
import { ShopMap } from './shop-map';

type ModalContainerProps = {
  item: Place;
};

export const ModalContainer = ({ item }: ModalContainerProps) => {
  const { openPhoneCall } = usePhoneCall();

  const close = () => {
    overlay.closeAll();
  };

  const handlePhoneCall = (number: string) => {
    openPhoneCall(number);
  };

  return (
    <div className="modal in-dialog">
      <div className="modal-top">
        <h2>{item.placeNm}</h2>
        <button type="button" className="btn close-btn" onClick={close}>
          <span>닫기</span>
        </button>
      </div>
      <div className="modal-body">
        <div className="shop-detail">
          <div className="shop-detail-map">
            <ShopMap item={item} />
          </div>
          <div className="vouc-detail-info">
            <dl>
              <dt>가맹점 정보</dt>
              <dd>
                <span>주소</span>
                <p>{item.adres}</p>
              </dd>
              <dd>
                <span>전화번호</span>
                <p>{item.telno}</p>
              </dd>
              <dd>
                <span>업종</span>
                <ul>{item.indutyInfo?.map((v) => <ol key={`dd_${v.indutyCd}`}>{v.indutyNm}</ol>)}</ul>
              </dd>
              <dd>
                <span>사용가능 바우처</span>
                <ul>{item.voucher?.map((v) => <ol key={`dd_${v.vouchId}`}>{v.vouchNm}</ol>)}</ul>
              </dd>
            </dl>
          </div>
        </div>
      </div>
      <div className={`btm-btn-area`}>
        <button
          type="button"
          className={clsx('btm-btn app', {
            disabled: !item.telno,
          })}
          onClick={() => handlePhoneCall(item.telno!)}
          disabled={!item.telno}
        >
          전화하기
        </button>
      </div>
    </div>
  );
};
