import { useEffect } from 'react';
import { useInView } from 'react-intersection-observer';
import { EmptyList } from '~/widgets/empty-list';
import { LoadingSpinner } from '~/widgets/loading/loading-spinner';
import { resetShopListInfiniteQuery } from '~/entities/shop/api/use-shop-infinite-list-query';
import { useMergedShopInfiniteList } from '~/entities/shop/lib/use-merged-shop-infinite-list';
import { ShopList } from '~/entities/shop/ui/shop-list';
import i18n from '~/shared/i18n/i18n';

export const ShopListContent = () => {
  const [ref, inView] = useInView();
  const { mergedList, hasNextPage, fetchNextPage, isLoading, isEmpty, totalCount } = useMergedShopInfiniteList();

  useEffect(() => {
    if (hasNextPage && inView) {
      fetchNextPage();
    }
  }, [fetchNextPage, hasNextPage, inView]);

  if (isLoading) {
    return <LoadingSpinner />;
  }

  return (
    <div className="shop-list">
      <p className="shop-cnt">총 {totalCount}개</p>
      <div className="shop-list-inner">
        {isEmpty ? (
          <EmptyList message={i18n.t('validation:noShopAvailable')} reset={resetShopListInfiniteQuery} />
        ) : (
          <ShopList list={mergedList} ref={ref} />
        )}
      </div>
    </div>
  );
};
