import { z } from 'zod';
import { ShopOrderByType, ShopResYnType, ShopViewType } from '~/entities/shop/types';

const shopHistoryListRequestSchema = z
  .object({
    sortType: z.nativeEnum(ShopOrderByType).optional(),
    resYn: z.nativeEnum(ShopResYnType).default(ShopResYnType.RES_NULL),
    searchText: z.string().optional(),
    latitude: z
      .string()
      .transform((val) => Number(val))
      .optional(),
    longitude: z
      .string()
      .transform((val) => Number(val))
      .optional(),
    searchRadius: z
      .string()
      .transform((val) => Number(val))
      .optional(),
    page: z
      .string()
      .transform((val) => Number(val))
      .optional(),
    pageSize: z
      .string()
      .transform((val) => Number(val))
      .optional(),
  })
  .optional()
  .default({});

export const searchParamSchema = z.object({
  mapSearch: shopHistoryListRequestSchema,
  listSearch: shopHistoryListRequestSchema,
  viewType: z.nativeEnum(ShopViewType).default(ShopViewType.SHOP_LIST),
});

export type ShopSearchParams = z.infer<typeof searchParamSchema>;
