import { ErrorBoundary } from '@suspensive/react';
import { QueryErrorResetBoundary } from '@tanstack/react-query';
import { memo, Suspense } from 'react';
import { useSearchParams } from 'react-router-dom';
import { FallbackErrorMessage } from '~/widgets/fallbacks/ui/fallback-error-message';
import { LoadingSpinner } from '~/widgets/loading/loading-spinner';
import { ShopListContent } from '~/entities/shop/ui/shop-list-content';
import { useFixScrollViewSafari } from '~/shared/lib/hooks';

export const ShopListContainer = memo(function ShopListContainer() {
  useFixScrollViewSafari();
  const [searchParams] = useSearchParams();

  return (
    <QueryErrorResetBoundary>
      {({ reset }) => (
        <ErrorBoundary fallback={FallbackErrorMessage} resetKeys={[searchParams.toString()]} onReset={reset}>
          <Suspense
            fallback={
              <div className="receipt-area">
                <LoadingSpinner />
              </div>
            }
          >
            <ShopListContent />
          </Suspense>
        </ErrorBoundary>
      )}
    </QueryErrorResetBoundary>
  );
});
