import { Fragment, useCallback, useEffect, useRef, useState } from 'react';
import { useShopMapList } from '~/entities/shop/lib/use-shop-map-list';
import { useShopSearch } from '~/entities/shop/lib/use-shop-search';
import { refreshGeolocationQuery } from '~/entities/shop/model/geolocation-model';
import { getShopLocationSearchUpdate } from '~/entities/shop/model/shop-location-search';
import { Place } from '~/entities/shop/model/types';
import { ShopViewType } from '~/entities/shop/types';
import { ModalContainer } from '~/entities/shop/ui/modal-container';
import MyLocationImg from '~/shared/assets/img/my_location_icon.png';
import { DEFAULT_latitude, DEFAULT_LONGITUDE } from '~/shared/constants/location';
import i18n from '~/shared/i18n/i18n';
import { overlay } from '~/shared/lib/overlay';
import { Dialog } from '~/shared/ui/dialogs/dialog';

function showMarker(_map: naver.maps.Map, _marker: naver.maps.Marker) {
  if (!_marker?.setMap) return;
  _marker.setMap(_map);
}

function hideMarker(_map: naver.maps.Map, _marker: naver.maps.Marker) {
  if (!_marker.setMap) return;
  _marker.setMap(null);
}

function disposeMarker(marker?: naver.maps.Marker) {
  if (!marker) return;
  naver.maps.Event.clearInstanceListeners(marker);
  marker.setMap(null);
}

function updateMarkers(_map: naver.maps.Map, _markers: naver.maps.Marker[]) {
  const mapBounds = _map.getBounds() as naver.maps.LatLngBounds;
  for (const marker of _markers) {
    const _position = marker.getPosition();
    if (mapBounds.hasLatLng(_position)) {
      showMarker(_map, marker);
    } else {
      hideMarker(_map, marker);
    }
  }
}

export const MapContainer = () => {
  // 전역맵생성
  const { data: mergedList } = useShopMapList();
  const { updateSearchParam, searchParam } = useShopSearch();
  const map = useRef<naver.maps.Map>();
  const [zoom, setZoom] = useState(15);
  const allMarkers = useRef<naver.maps.Marker[]>([]);
  const myLocationMarker = useRef<naver.maps.Marker>();
  const disposed = useRef(false);
  const handleClickItem = (clickedItem: Place) => () => {
    overlay.exclusiveOpen(({ isOpen, close, unmount }) => {
      return (
        <Dialog afterLeave={unmount} open={isOpen} onClose={close} buttonLabel={[]}>
          <ModalContainer item={clickedItem} />
        </Dialog>
      );
    });
  };

  const handleNaverMapCenterChange = () => {
    const mapBounds = map.current!.getBounds() as naver.maps.LatLngBounds;
    updateSearchParam({
      ...searchParam.mapSearch,
      latitude: mapBounds.getCenter().lat(),
      longitude: mapBounds.getCenter().lng(),
      viewType: ShopViewType.SHOP_MAP,
    });
  };

  useEffect(() => {
    if (map.current) {
      processNaverMap();
    }
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [mergedList]);

  const processNaverMap = useCallback(() => {
    allMarkers.current.forEach(disposeMarker);
    allMarkers.current = [];
    const mapList: Place[] = [...mergedList.list];
    const markers: naver.maps.Marker[] = [];
    const mapBounds = map.current?.getBounds() as naver.maps.LatLngBounds;
    for (const item of mapList!) {
      const _position = new naver.maps.LatLng(Number(item.latitude), Number(item.longitude));
      if (mapBounds.hasLatLng(_position)) {
        const marker = new naver.maps.Marker({
          map: map.current!,
          position: _position,
          title: item.placeNm ?? '',
          zIndex: 100,
          icon: {
            content: [
              `<div class="map-marker-info ${item.isMyVoucher ? 'use-voc' : ''}">`,
              '<div class="map-marker-info-inner">',
              '<p>',
              item.placeNm,
              '</p>',
              '<span>',
              item.indutyInfo && item.indutyInfo.length > 0 ? item.indutyInfo[0].indutyNm : '',
              '</span>',
              '</div>',
              '</div>',
            ].join(''),
            size: new naver.maps.Size(38, 58),
            anchor: new naver.maps.Point(19, 58),
          },
        });
        markers.push(marker);
      }
    }
    // 해당 마커의 인덱스를 seq라는 클로저 변수로 저장하는 이벤트 핸들러를 반환합니다.
    for (let i = 0, ii = markers.length; i < ii; i++) {
      naver.maps.Event.addListener(markers[i], 'click', handleClickItem(mapList[i]));
      naver.maps.Event.addListener(markers[i], 'mouseover', () => {
        markers[i].setZIndex(110);
      });
      naver.maps.Event.addListener(markers[i], 'mouseout', () => {
        markers[i].setZIndex(100);
      });
    }
    allMarkers.current = markers;
    updateMarkers(map.current!, allMarkers.current);
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [mergedList]);

  const fnMyLocationMarker = () => {
    const setMarker = (lat: number, lng: number) => {
      disposeMarker(myLocationMarker.current);
      myLocationMarker.current = new naver.maps.Marker({
        position: new naver.maps.LatLng(lat, lng),
        map: map.current,
        icon: {
          url: MyLocationImg,
          size: new naver.maps.Size(20, 20),
          origin: new naver.maps.Point(0, 0),
          anchor: new naver.maps.Point(25, 26),
        },
      });
      myLocationMarker.current!.setMap(map.current!);
      map.current!.setCenter(new naver.maps.LatLng(lat, lng));
    };
    void refreshGeolocationQuery().then((geolocation) => {
      if (disposed.current || !map.current || !geolocation) return;

      updateSearchParam(getShopLocationSearchUpdate(geolocation));
      if (geolocation.position) {
        setMarker(geolocation.position.latitude, geolocation.position.longitude);
        return;
      }

      disposeMarker(myLocationMarker.current);
      myLocationMarker.current = undefined;
      map.current.setCenter(new naver.maps.LatLng(DEFAULT_latitude, DEFAULT_LONGITUDE));
    });
  };

  useEffect(() => {
    if (!window.naver?.maps) return;

    disposed.current = false;

    //최초 맵 생성
    if (!map.current) {
      const locationBtnHtml = `<button type="button" class="btn map-btn loc-current env-bottom-margin"><span>${i18n.t('moveToCurrentLocation')}</span></button>`;
      const searchThisAreaBtnHtml = `<button type="button" class="map-btn loc-reset env-bottom-margin">${i18n.t('searchThisArea')}</button>`;
      map.current = new naver.maps.Map(document.getElementById('map') as HTMLElement, {
        center: new naver.maps.LatLng(DEFAULT_latitude, DEFAULT_LONGITUDE),
        zoom: zoom,
      });
      const mapInstance = map.current;
      let locationControl: naver.maps.CustomControl | undefined;
      let searchAreaControl: naver.maps.CustomControl | undefined;
      let locationControlElement: HTMLElement | undefined;
      let searchAreaControlElement: HTMLElement | undefined;
      const handleLocationControlClick = () => fnMyLocationMarker();
      const handleSearchAreaControlClick = () => handleNaverMapCenterChange();
      const initListener = naver.maps.Event.once(mapInstance, 'init', function () {
        if (disposed.current) return;

        locationControl = new naver.maps.CustomControl(locationBtnHtml, {
          position: naver.maps.Position.BOTTOM_CENTER,
        });
        searchAreaControl = new naver.maps.CustomControl(searchThisAreaBtnHtml, {
          position: naver.maps.Position.BOTTOM_CENTER,
        });
        locationControl.setMap(mapInstance);
        locationControlElement = locationControl.getElement();
        naver.maps.Event.addDOMListener(locationControlElement, 'click', handleLocationControlClick);
        searchAreaControl.setMap(mapInstance);
        searchAreaControlElement = searchAreaControl.getElement();
        naver.maps.Event.addDOMListener(searchAreaControlElement, 'click', handleSearchAreaControlClick);
      });

      const zoomListener = naver.maps.Event.addListener(mapInstance, 'zoom_changed', function () {
        setZoom(mapInstance.getZoom());
        // updateMarkers(map.current!, allMarkers.current);
      });

      fnMyLocationMarker();

      return () => {
        disposed.current = true;
        naver.maps.Event.removeListener([initListener, zoomListener]);

        if (locationControlElement) {
          naver.maps.Event.removeDOMListener(locationControlElement, 'click', handleLocationControlClick);
        }
        if (searchAreaControlElement) {
          naver.maps.Event.removeDOMListener(searchAreaControlElement, 'click', handleSearchAreaControlClick);
        }

        locationControl?.setMap(null);
        searchAreaControl?.setMap(null);
        allMarkers.current.forEach(disposeMarker);
        allMarkers.current = [];
        disposeMarker(myLocationMarker.current);
        myLocationMarker.current = undefined;
        naver.maps.Event.clearInstanceListeners(mapInstance);
        mapInstance.destroy();
        map.current = undefined;
      };
    }
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [window.naver?.maps]);

  return (
    <Fragment>
      <div id="map" className="shop-map"></div>
    </Fragment>
  );
};
