import { useShopListMapQuery } from '~/entities/shop/api/use-shop-list-query';
import { useShopSearch } from '~/entities/shop/lib/use-shop-search';
import { ShopOrderByType, ShopResYnType } from '~/entities/shop/types';

export const useShopMapList = () => {
  const { searchParam } = useShopSearch();
  const { sortType, searchText, latitude, longitude, resYn } = searchParam.mapSearch;
  const { data, refetch, isLoading } = useShopListMapQuery({
    sortType: sortType || ShopOrderByType.가까운순,
    searchText,
    latitude,
    longitude,
    searchRadius: 1000,
    page: 1,
    pageSize: 30,
    resYn: resYn ?? ShopResYnType.RES_NULL,
  });

  return {
    data,
    totalCount: data?.totalCount || 0,
    refetch,
    isLoading,
    isEmpty: !data,
    searchParam,
  };
};
