import { notifyNaverMapsReady } from '~/entities/shop/lib/naver-map-sdk';
import { GOV_CLIENT_ID } from '~/shared/config/environment';

// Create a wrapper to handle Suspense loading for scripts
const createResource = (promise: Promise<any>) => {
  let status = 'pending';
  let result: any;
  const suspender = promise.then(
    (r) => {
      status = 'success';
      result = r;
    },
    (e) => {
      status = 'error';
      result = e;
    },
  );

  return {
    read() {
      if (status === 'pending') {
        throw suspender;
      } else if (status === 'error') {
        throw result;
      } else if (status === 'success') {
        return result;
      }
    },
  };
};

// 기존 스크립트 제거 함수
const removeExistingScript = () => {
  const existingScript = document.querySelector('script[src*="maps.js"]');
  if (existingScript) {
    existingScript.remove();
  }
  // naver 객체 초기화
  (window as any).naver = undefined;
};

// Create a promise for loading the Naver Map script
const naverMapScriptPromise = new Promise<boolean>((resolve, reject) => {
  // 기존 스크립트 제거
  removeExistingScript();

  // 캐시 방지를 위한 타임스탬프 추가
  const script = document.createElement('script');

  // callback 함수 정의
  (window as any).initMap = () => {
    notifyNaverMapsReady();
    resolve(true);
  };

  script.src = `https://oapi.map.naver.com/openapi/v3/maps.js?govClientId=${GOV_CLIENT_ID}&callback=initMap&submodules=geocoder`;
  script.async = true;
  script.onerror = (error) => {
    console.error('Failed to load Naver Map:', error);
    reject(error);
  };

  document.head.appendChild(script);
});

// Create a resource for the Naver Map script
const naverMapResource = createResource(naverMapScriptPromise);

// Script loader component with Suspense support
export const NaverMapScript = ({ children }: { children: React.ReactNode }) => {
  naverMapResource.read();
  return <>{children}</>;
};
