import { useCallback } from 'react';
import { ShopSearchParams } from '~/entities/shop/model/search-param';
import { ShopViewType } from '~/entities/shop/types';
import { useShopSearchParams } from './use-shop-search-params';

export const useShopSearch = () => {
  const { searchParams, updateSearchParams, resetSearchParams } = useShopSearchParams();

  const updateSearchParam = useCallback(
    (
      updates: Partial<ShopSearchParams['mapSearch'] & ShopSearchParams['listSearch']> & { viewType?: ShopViewType },
    ) => {
      const { viewType, ...params } = updates;

      // viewType이 변경되면 해당하는 검색 파라미터도 함께 업데이트
      if (viewType) {
        updateSearchParams({
          viewType,
          // 지도 뷰로 변경 시 mapSearch 업데이트
          ...(viewType === ShopViewType.SHOP_MAP && {
            mapSearch: params,
          }),
          // 리스트 뷰로 변경 시 listSearch 업데이트
          ...(viewType === ShopViewType.SHOP_LIST && {
            listSearch: params,
          }),
        });
        return;
      }

      // viewType이 없는 경우 현재 viewType에 따라 업데이트
      updateSearchParams({
        ...(searchParams.viewType === ShopViewType.SHOP_MAP && {
          mapSearch: params,
        }),
        ...(searchParams.viewType === ShopViewType.SHOP_LIST && {
          listSearch: params,
        }),
      });
    },
    [searchParams.viewType, updateSearchParams],
  );

  return {
    searchParam: searchParams,
    updateSearchParam,
    resetSearchParam: resetSearchParams,
  };
};
