import type { GeolocationData } from '~/entities/shop/model/geolocation-model';
import { ShopResYnType } from '~/entities/shop/types';
import { DEFAULT_latitude, DEFAULT_LONGITUDE } from '~/shared/constants/location';

export const getShopLocationSearchUpdate = (geolocation: GeolocationData) => {
  if (geolocation.position) {
    return {
      latitude: geolocation.position.latitude,
      longitude: geolocation.position.longitude,
      resYn: ShopResYnType.RES_Y,
    } as const;
  }

  return {
    latitude: DEFAULT_latitude,
    longitude: DEFAULT_LONGITUDE,
    resYn: geolocation.failureReason === 'permission-denied' ? ShopResYnType.RES_N : ShopResYnType.RES_NULL,
  } as const;
};
