import { useEffect } from 'react';
import { Place } from '~/entities/shop/model/types';
import { GOV_CLIENT_ID } from '~/shared/config/environment';
import { useScript } from '~/shared/lib/hooks/use-script';

type ShopMapProps = {
  item: Place;
};
export const ShopMap = ({ item }: ShopMapProps) => {
  const [loading] = useScript(
    `https://oapi.map.naver.com/openapi/v3/maps.js?govClientId=${GOV_CLIENT_ID}&callback=initMap&submodules=geocoder`,
  );
  useEffect(() => {
    if (loading) return;
    if (!window?.naver?.maps) return;

    const lat = Number(item.latitude),
      lng = Number(item.longitude);

    const map = new naver.maps.Map(document.getElementById('shopMap') as HTMLElement, {
      center: new naver.maps.LatLng(lat, lng),
      zoom: 15,
    });
    const marker = new naver.maps.Marker({
      position: new naver.maps.LatLng(lat, lng),
      map: map,
    });
    marker.setMap(map);

    return () => {
      naver.maps.Event.clearInstanceListeners(marker);
      marker.setMap(null);
      naver.maps.Event.clearInstanceListeners(map);
      map.destroy();
    };
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [loading, naver.maps]);
  return <div id="shopMap" className="shop-map"></div>;
};
