import { InfiniteData, useSuspenseInfiniteQuery } from '@tanstack/react-query';
import { shopApi } from '~/entities/shop/api/shop-api';
import { ShopHistoryListRequestDTO, ShopListResponseDTO } from '~/entities/shop/dtos/shop-list';
import { DEFAULT_PLACE_READ_LIST_BY_RADIUS, DEFAULT_SHOP_LIST_PAGE_SIZE } from '~/entities/shop/model/constants';
import { ShopResYnType } from '~/entities/shop/types';
import { CBDCAxiosError } from '~/shared/@types/error';
import { InfiniteQueryOptions } from '~/shared/@types/query';
import { queries } from '~/shared/api/query-keys';
import { getGlobalQueryClient } from '~/shared/config/query';
import i18n from '~/shared/i18n/i18n';

export const useShopListInfiniteQuery = (
  param: ShopHistoryListRequestDTO = DEFAULT_PLACE_READ_LIST_BY_RADIUS,
  options?: InfiniteQueryOptions<
    ShopListResponseDTO,
    CBDCAxiosError,
    InfiniteData<ShopListResponseDTO>,
    readonly unknown[],
    ShopHistoryListRequestDTO
  >,
) => {
  const query = useSuspenseInfiniteQuery<
    ShopListResponseDTO,
    CBDCAxiosError,
    InfiniteData<ShopListResponseDTO>,
    readonly unknown[],
    ShopHistoryListRequestDTO
  >({
    queryKey: queries.voucher.placeReadListByRadiusInfiniteList({ placeSearchParam: param }).queryKey,
    queryFn: async ({ pageParam = param }) => await shopApi.getPlaceReadListByRadius({ ...pageParam }),
    initialPageParam: param,
    getNextPageParam: (lastPage, allPages) => {
      const currentPage = allPages.length;
      const pageSize = param.pageSize ?? DEFAULT_SHOP_LIST_PAGE_SIZE;
      const totalPages = Math.ceil(lastPage.totalCount / pageSize);

      if (currentPage < totalPages) {
        return {
          ...param,
          page: currentPage + 1,
        };
      }
      return undefined;
    },
    select: (data) => {
      return {
        ...data,
        pages: data.pages.map((page) => ({
          ...page,
          list: page.list.map((item) => ({
            ...item,

            DISTANCE_NM:
              param.resYn === ShopResYnType.RES_Y
                ? `${Math.trunc(Number(item.distance))}m`
                : param.resYn === ShopResYnType.RES_N
                  ? i18n.t('common:notAllowedLocation')
                  : i18n.t('common:notFoundLocation'),
            // DISTANCE_NM:
            //   param.resYn === ShopResYnType.RES_Y
            //     ? formatDistance(
            //         calculateDistance(
            //           Number(param.latitude) ?? null,
            //           Number(param.longitude) ?? null,
            //           Number(item.latitude),
            //           Number(item.longitude),
            //         ),
            //       )
            //     : i18n.t('common:notAllowedLocation'),
          })),
        })),
      };
    },
    gcTime: 5 * 60 * 1000,
    staleTime: 0,
    refetchOnMount: false,
    refetchOnWindowFocus: false,
    refetchOnReconnect: false,
    ...options,
  });

  return { ...query };
};

export const resetShopListInfiniteQuery = () => {
  const queryClient = getGlobalQueryClient();
  queryClient.invalidateQueries({
    queryKey: queries.voucher.placeReadListByRadiusInfiniteList._def,
  });
};
