import { isEqual } from 'lodash-es';
import { memo, useEffect, useRef } from 'react';
import { ShopHistoryListRequestDTO } from '~/entities/shop/dtos/shop-list';
import { useShopSearch } from '~/entities/shop/lib/use-shop-search';
import { ShopOrderByType, ShopViewType } from '~/entities/shop/types';

type ShopSearchParamsProviderProps = {
  params?: {
    mapSearch?: Partial<ShopHistoryListRequestDTO>;
    listSearch?: Partial<ShopHistoryListRequestDTO>;
    viewType: ShopViewType;
  };
  children: React.ReactNode;
};

const DEFAULT_SEARCH_PARAMS = {
  sortType: ShopOrderByType.가까운순,
  searchText: '',
  searchRadius: 1000,
} as const;

export const ShopSearchParamsProvider = memo(function ShopSearchParamsProvider({
  params,
  children,
}: ShopSearchParamsProviderProps) {
  const { updateSearchParam } = useShopSearch();
  const prevParams = useRef(params);

  useEffect(() => {
    if (params && !isEqual(params, prevParams.current)) {
      const { viewType } = params;
      const searchParams = viewType === ShopViewType.SHOP_MAP ? params.mapSearch : params.listSearch;

      // undefined 값은 제외하고 병합
      const mergedParams = {
        ...DEFAULT_SEARCH_PARAMS,
        ...(searchParams &&
          Object.fromEntries(Object.entries(searchParams).filter(([_, value]) => value !== undefined))),
      };

      updateSearchParam({
        viewType,
        ...mergedParams,
      });

      prevParams.current = params;
    }
  }, [params, updateSearchParam]);

  return <>{children}</>;
});
